import sys
from collections import deque

def build_opt(pre, ino):
    pos = {v: i for i, v in enumerate(ino)}
    def dfs(pl, pr, il, ir):
        if pl > pr: return None
        root = pre[pl]
        i = pos[root]
        left_size = i - il
        return (root, dfs(pl + 1, pl + left_size, il, i - 1), dfs(pl + left_size + 1, pr, i + 1, ir))
    return dfs(0, len(pre) - 1, 0, len(ino) - 1)

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    pre = list(map(int, data[1:1+n]))
    ino = list(map(int, data[1+n:1+2*n]))
    r = build_opt(pre, ino)
    if not r:
        print('n'); sys.exit(0)
    from collections import deque
    res = []
    q = deque([r])
    while q:
        t = q.popleft()
        res.append(str(t[0]))
        q.append(t[1] or 'n')
        q.append(t[2] or 'n')
    while res and res[-1] == 'n':
        res.pop()
    print(' '.join(res))

